/// Updates credential metadata or rotates its write-only secret. See [vaults](https://developers.openai.com/api/docs/guides/agents-api/tools/vaults).
#[bon::builder]
pub async fn rotate_vault_credential(
    configuration: &configuration::Configuration,
    vault_id: &str,
    credential_id: &str,
    rotate_vault_credential_params: Option<models::RotateVaultCredentialParams>,
) -> Result<models::VaultCredentialResource, Error<RotateVaultCredentialError>> {
    // add a prefix to parameters to efficiently prevent name collisions
    let p_path_vault_id = vault_id;
    let p_path_credential_id = credential_id;
    let p_body_rotate_vault_credential_params = rotate_vault_credential_params;

    let uri_str = format!(
        "{}/vaults/{vault_id}/credentials/{credential_id}",
        configuration.base_path,
        vault_id = crate::apis::urlencode(p_path_vault_id),
        credential_id = crate::apis::urlencode(p_path_credential_id)
    );
    let mut req_builder = configuration
        .client
        .request(reqwest::Method::POST, &uri_str);

    if let Some(ref user_agent) = configuration.user_agent {
        req_builder = req_builder.header(reqwest::header::USER_AGENT, user_agent.clone());
    }
    if let Some(ref token) = configuration.bearer_access_token {
        req_builder = req_builder.bearer_auth(token.to_owned());
    };
    req_builder = req_builder.json(&p_body_rotate_vault_credential_params);

    let req = req_builder.build()?;
    let resp = configuration.client.execute(req).await?;

    let status = resp.status();
    let content_type = resp
        .headers()
        .get("content-type")
        .and_then(|v| v.to_str().ok())
        .unwrap_or("application/octet-stream");
    let content_type = super::ContentType::from(content_type);

    if !status.is_client_error() && !status.is_server_error() {
        let content = resp.text().await?;
        match content_type {
            ContentType::Json => serde_json::from_str(&content).map_err(Error::from),
            ContentType::Text => return Err(Error::from(serde_json::Error::custom("Received `text/plain` content type response that cannot be converted to `models::VaultCredentialResource`"))),
            ContentType::Unsupported(unknown_type) => return Err(Error::from(serde_json::Error::custom(format!("Received `{unknown_type}` content type response that cannot be converted to `models::VaultCredentialResource`")))),
        }
    } else {
        let content = resp.text().await?;
        let entity: Option<RotateVaultCredentialError> = serde_json::from_str(&content).ok();
        Err(Error::ResponseError(Box::new(ResponseContent {
            status,
            content,
            entity,
        })))
    }
}
